(function(){
  function mount({root,state,getRows,domain:CpaDomain,format,now=()=>new Date()}){
    const $=selector=>root.querySelector(selector),$$=selector=>[...root.querySelectorAll(selector)];
    const {esc,num:fmtNum,money:fmtMoney,pct:fmtPct,date:dateLabel,parseDate:parseBrazilianDate,campaignName}=format;
    const campaignIdentity=name=>({name:campaignName(name)});
    const cpaReportRows=()=>getRows({mode:state.cpaMode,start:cpaDateValue('#cpaDateStart'),end:cpaDateValue('#cpaDateEnd')});
    function cpaDateValue(selector){return parseBrazilianDate($(selector).value)}
    function setCpaDateValue(selector,iso){$(selector).value=iso?dateLabel(iso):''}
    function defaultDateRange(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now()).map(part=>[part.type,part.value])),today=`${parts.year}-${parts.month}-${parts.day}`,[year,month,day]=today.split('-').map(Number),startMonth=new Date(Date.UTC(year,month-3,1)),startDay=Math.min(day,new Date(Date.UTC(startMonth.getUTCFullYear(),startMonth.getUTCMonth()+1,0)).getUTCDate()),start=new Date(Date.UTC(startMonth.getUTCFullYear(),startMonth.getUTCMonth(),startDay)).toISOString().slice(0,10);return[start,today]}
    function cpaSelect(selector,items,current,allLabel){const el=$(selector),values=[...new Set(items)].sort((a,b)=>a.localeCompare(b,'pt-BR',{numeric:true,sensitivity:'base'}));el.innerHTML=`<option value="all">${allLabel}</option>`+values.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');el.value=values.includes(current)?current:'all';return el.value}
    function renderSummary(){const all=cpaReportRows();state.cpaAccount=cpaSelect('#cpaAccount',all.map(x=>x.account),state.cpaAccount,'Todas');state.cpaProduct=cpaSelect('#cpaProduct',all.map(x=>x.product),state.cpaProduct,'Todos');state.cpaCountry=cpaSelect('#cpaCountry',all.flatMap(x=>x.check.countries),state.cpaCountry,'Todos');state.cpaPlatform=cpaSelect('#cpaPlatform',all.map(x=>x.check.platform),state.cpaPlatform,'Todas');$('#cpaStatus').value=state.cpaStatus;$('#cpaCurrentMode').classList.toggle('active',state.cpaMode==='current');$('#cpaHistoryMode').classList.toggle('active',state.cpaMode==='history');const rows=CpaDomain.filterRows(all,state),{list,summaries,totalInvestment,totalConversions,totalCommission,totalProfit,totalRoi,alerts,selectedRange}=CpaDomain.summarizeRows(rows,state.cpaSelectedRange,fmtNum);state.cpaSelectedRange=selectedRange;$('#cpaKpis').innerHTML=[['Campanhas',rows.length,`${rows.filter(x=>x.status==='ativa').length} ativas`],['Faixas em uso',list.length,'detectadas automaticamente'],['Investimento',fmtMoney(totalInvestment),'no período'],['Conversões',fmtNum(totalConversions),'oficiais + provisórias'],['ROI geral',totalRoi==null?'—':fmtPct(totalRoi),`Lucro ${fmtMoney(totalProfit)}`],['Divergências',alerts,alerts?'exigem revisão':'faixas conferidas']].map((x,i)=>`<div class="card cpa-kpi"><span>${x[0]}</span><strong class="${i===5&&alerts?'negative':''}">${x[1]}</strong><small>${x[2]}</small></div>`).join('');$('#cpaSummaryBody').innerHTML=summaries.length?summaries.map(g=>`<tr class="${g.key===state.cpaSelectedRange?'selected':''}" data-range="${esc(g.key)}"><td><strong>${esc(g.label)}</strong></td><td class="num">${g.rows.length}</td><td class="num positive">${g.active}</td><td class="num">${fmtMoney(g.investment)}</td><td class="num">${fmtNum(g.conversions)}</td><td class="num">${g.actualCpa==null?'—':fmtMoney(g.actualCpa)}</td><td class="num">${fmtMoney(g.commission)}</td><td class="num ${g.profit>=0?'positive':'negative'}">${fmtMoney(g.profit)}</td><td class="num ${g.roi>=0?'positive':'negative'}">${g.roi==null?'—':fmtPct(g.roi)}</td><td class="num ${g.divergences?'negative':''}">${g.divergences}</td></tr>`).join(''):'<tr><td colspan="10" class="empty">Nenhuma campanha encontrada para os filtros selecionados.</td></tr>';const maxRoi=Math.max(1,...summaries.map(x=>Math.abs(x.roi||0)));$('#cpaChart').innerHTML=summaries.length?summaries.map(g=>`<div class="cpa-chart-row"><strong>${esc(g.label)}</strong><div class="cpa-chart-track"><div class="cpa-chart-fill" style="width:${Math.abs(g.roi||0)/maxRoi*100}%;background:${g.roi!=null&&g.roi<0?'var(--red)':''}"></div></div><span class="${g.roi!=null&&g.roi>=0?'positive':'negative'}">${g.roi==null?'—':fmtPct(g.roi)}</span></div>`).join(''):'<div class="muted">Sem dados para o gráfico.</div>';const selected=summaries.find(x=>x.key===state.cpaSelectedRange),detail=selected?.rows||rows;$('#cpaDetailTitle').textContent=selected?`Detalhamento · Faixa ${selected.label}`:'Detalhamento das campanhas';$('#cpaDetailCount').textContent=`${detail.length} campanha${detail.length===1?'':'s'}`;const checkLabel={ok:'Confere',review:'Revisar',bad:'Divergente',missing:'Sem dado'};$('#cpaDetailBody').innerHTML=detail.length?detail.map(r=>`<tr><td class="name" title="${esc(r.name)}">${esc(campaignIdentity(r.name).name)}</td><td>${esc(r.account)}</td><td>${r.status==='ativa'?'Ativa':'Pausada'}</td><td class="num">${r.check.range==null?'—':fmtPct(r.check.range)}</td><td class="num">${r.check.target==null?'—':`${r.check.targetCurrency==='USD'?'US$':'R$'} ${fmtNum(r.check.target,2)}`}</td><td class="num">${r.check.calculated==null?'—':fmtPct(r.check.calculated)}</td><td class="num ${r.check.status==='bad'?'negative':r.check.status==='review'?'cpa-check review':''}">${r.check.difference==null?'—':`${r.check.difference>0?'+':''}${fmtNum(r.check.difference,2)} p.p.`}</td><td><span class="cpa-check ${r.check.status}">${checkLabel[r.check.status]}</span></td><td class="num">${r.totals.investment==null?'—':fmtMoney(r.totals.investment)}</td><td class="num">${r.totals.conversions==null?'—':fmtNum(r.totals.conversions)}</td><td class="num">${r.totals.actualCpa==null?'—':fmtMoney(r.totals.actualCpa)}</td><td class="num">${r.totals.roi==null?'—':fmtPct(r.totals.roi)}</td></tr>`).join(''):'<tr><td colspan="12" class="empty">Nenhuma campanha para detalhar.</td></tr>';$$('#cpaSummaryBody tr[data-range]').forEach(tr=>tr.onclick=()=>{state.cpaSelectedRange=tr.dataset.range;renderCpaReport()})}
    function renderCpaImpressionsChart(){const rows=CpaDomain.filterRows(cpaReportRows(),state),groups=new Map();for(const row of rows){const key=row.check.range==null?'other':String(row.check.range),group=groups.get(key)||{key,label:row.check.range==null?'Outras':`${fmtNum(row.check.range,row.check.range%1?1:0)}%`,range:row.check.range,impressions:0};group.impressions+=Number(row.totals.impressions||0);groups.set(key,group)}const list=[...groups.values()].sort((a,b)=>(a.range??999)-(b.range??999)),max=Math.max(1,...list.map(x=>x.impressions));$('#cpaImpressionsChart').innerHTML=list.length?list.map(g=>`<div class="cpa-chart-row"><strong>${esc(g.label)}</strong><div class="cpa-chart-track"><div class="cpa-chart-fill" style="width:${g.impressions/max*100}%"></div></div><span>${fmtNum(g.impressions)}</span></div>`).join(''):'<div class="muted">Sem dados para o gráfico.</div>'}
    function cpaProductsByRange(rows){return CpaDomain.productsByRange(rows).map(group=>({...group,label:group.range==null?'Sem faixa':fmtNum(group.range,group.range%1?1:0)+'%'}))}
    function renderCpaProductsByRange(){const rows=CpaDomain.filterRows(cpaReportRows(),state),groups=cpaProductsByRange(rows),max=Math.max(1,...groups.map(x=>x.count));$('#cpaProductsByRange').innerHTML=groups.length?groups.map(group=>`<div class="account-bar-row"><span>${esc(group.label)}</span><div class="account-bar-track"><div class="account-bar-fill" style="width:${group.count/max*100}%"></div></div><strong>${group.count}</strong></div>`).join(''):'<div class="muted">Sem dados.</div>'}
    function renderCpaReport(){if(!$('#cpaDateStart').value||!$('#cpaDateEnd').value)state.cpaDatesReady=false;if(!state.cpaDatesReady){const[start,end]=defaultDateRange();setCpaDateValue('#cpaDateStart',start);setCpaDateValue('#cpaDateEnd',end);state.cpaDatesReady=true}const result=renderSummary();for(const selector of ['#cpaDateStart','#cpaDateEnd']){const input=$(selector),iso=parseBrazilianDate(input.value);input.setAttribute('aria-invalid',String(!!input.value&&!iso));if(/^\d{4}-\d{2}-\d{2}$/.test(input.value))setCpaDateValue(selector,input.value)}renderCpaImpressionsChart();renderCpaProductsByRange();return result}
    $('#cpaStatus').onchange=e=>{state.cpaStatus=e.target.value;renderCpaReport()};$('#cpaAccount').onchange=e=>{state.cpaAccount=e.target.value;renderCpaReport()};$('#cpaProduct').onchange=e=>{state.cpaProduct=e.target.value;renderCpaReport()};$('#cpaCountry').onchange=e=>{state.cpaCountry=e.target.value;renderCpaReport()};$('#cpaPlatform').onchange=e=>{state.cpaPlatform=e.target.value;renderCpaReport()};$('#cpaDateStart').onchange=renderCpaReport;$('#cpaDateEnd').onchange=renderCpaReport;$('#cpaCurrentMode').onclick=()=>{state.cpaMode='current';renderCpaReport()};$('#cpaHistoryMode').onclick=()=>{state.cpaMode='history';renderCpaReport()};
    return Object.freeze({render:renderCpaReport});
  }
  window.CpaView=Object.freeze({mount});
})();
